def load_moment(device: str = "cpu", model_name: str = "AutonLab/MOMENT-1-small",
                disable_revin: bool = False, norm_type: str = "revin") -> nn.Module:
    """Load MOMENT pretrained model (small, base, or large)."""
    from momentfm import MOMENTPipeline

    model = MOMENTPipeline.from_pretrained(
        model_name,
        model_kwargs={"task_name": "reconstruction"},
    )
    model.init()
    model = model.to(device)
    model.eval()

    if disable_revin:
        class _IdentityNormalizer(nn.Module):
            """Replace RevIN with identity for controlled ablation."""
            def forward(self, x, mode="norm", mask=None):
                return x
        model.normalizer = _IdentityNormalizer()

    if norm_type == "batchnorm":
        class _BatchNormNormalizer(nn.Module):
            """Replace RevIN with BatchNorm1d for generalization test."""
            def __init__(self):
                super().__init__()
                self.bn = nn.BatchNorm1d(1)
            def forward(self, x, mode="norm", mask=None):
                if mode == "norm":
                    return self.bn(x)
                return x  # denorm is identity (BN has no reversible inverse)
        model.normalizer = _BatchNormNormalizer().to(device)
    elif norm_type == "groupnorm":
        class _GroupNormNormalizer(nn.Module):
            """Replace RevIN with GroupNorm for generalization test."""
            def __init__(self):
                super().__init__()
                self.gn = nn.GroupNorm(1, 1)  # 1 group, 1 channel
            def forward(self, x, mode="norm", mask=None):
                if mode == "norm":
                    return self.gn(x)
                return x
        model.normalizer = _GroupNormNormalizer().to(device)

    return model


def load_chronos(device: str = "cpu", model_name: str = "amazon/chronos-t5-small") -> nn.Module:
    """Load Chronos T5 model. Returns the T5 encoder-decoder model."""
    from chronos import ChronosPipeline
    pipe = ChronosPipeline.from_pretrained(
        model_name, device_map=device, torch_dtype=torch.float32,
    )
    # Return the inner T5 model (has .encoder with .block layers)
    return pipe.model.model


def load_moirai(device: str = "cpu", model_name: str = "Salesforce/moirai-1.1-R-small") -> nn.Module:
    """Load Moirai model. Returns the MoiraiModule with .encoder."""
    from uni2ts.model.moirai import MoiraiModule
    model = MoiraiModule.from_pretrained(model_name)
    model = model.to(device)

