input.command:
cd /Users/hungpq2412/neuralips26; echo "=== paper tab:self_routed SR-MoA numbers ==="; awk '/label\{tab:self_routed\}/{f=NR} f&&NR>=f&&NR<=f+30{print NR": "$0}' main.tex | grep -iE "ETTh|ETTm|Weather|Elec|Raw|Hidden|gated|&" | head -20; echo; echo "=== '13' or '23-38' or '42' near SR-MoA claims ==="; grep -nE "13.*42|23.*38|13\\\\%|42\\\\%" main.tex | head; echo; echo "=== raw SR-MoA data: compute frozen H96 means ==="; python3 -c "
import glob, json, collections
files = [f for f in glob.glob('results/self_routed_moa/*.json') if 'gated' in f and 'ri-hidden' not in f and '_bb-' not in f]
by = collections.defaultdict(list)
for f in files:
    d = json.load(open(f))
    ds = d.get('dataset'); 
    # find SR-MoA raw MSE key
    mse = d.get('sr_moa',{}).get('mse') or d.get('mse') or d.get('sr_moa_raw',{}).get('mse')
    if ds and mse: by[ds].append(mse)
print('SR-MoA frozen H96 raw means (from results/self_routed_moa/):')
for ds in ['ETTh1','ETTh2','ETTm1','ETTm2','Weather','Electricity']:
    if ds in by: print(f'  {ds:<12} {sum(by[ds])/len(by[ds]):.4f}  (n={len(by[ds])})')
" 2>&1 | head -20

cd /Users/hungpq2412/neuralips26; echo "=== tab:rrmoa RR-MoA frozen numbers ==="; awk '/label\{tab:rrmoa\}/{f=NR} f&&NR>=f&&NR<=f+30{print NR": "$0}' main.tex | grep -iE "ETTh|ETTm|Weather|Elec" | head -12; echo; echo "=== compute SR-MoA improvement over RR-MoA from paper tables ==="; python3 -c "
srmoa = {'ETTh1':0.464,'ETTh2':0.577,'ETTm1':0.388,'ETTm2':0.366,'Weather':0.222,'Electricity':0.260}
# RR-MoA frozen H96 canonical (from memory, tab:rrmoa+reinjection); will cross-check vs printed tab:rrmoa above
rrmoa = {'ETTh1':0.690,'ETTh2':0.788,'ETTm1':0.571,'ETTm2':0.588,'Weather':0.289,'Electricity':0.386}
imps=[]
for ds in srmoa:
    imp = 100*(rrmoa[ds]-srmoa[ds])/rrmoa[ds]; imps.append(imp)
    print(f'  {ds:<12} SR-MoA={srmoa[ds]:.3f}  RR-MoA={rrmoa[ds]:.3f}  improvement={imp:.1f}%')
print(f'  RANGE: {min(imps):.0f}-{max(imps):.0f}%  (paper prose says 13-42%)')
"

